CREATE OR REPLACE FUNCTION ctrlz_fn.admin_revoke_user_sessions(p_user_id uuid)
RETURNS integer
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
